import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { API_URL, testConnection } from '../utils/api';

const ImageProcessor = ({ colorblindType, mode }) => {
  const [originalImage, setOriginalImage] = useState(null);
  const [processedImage, setProcessedImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [serverConnected, setServerConnected] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    testConnection().then(r => setServerConnected(r.success));
  }, []);

  const handleFileSelect = e => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      setOriginalImage(ev.target.result);
      setProcessedImage(null);
    };
    reader.readAsDataURL(file);
  };

  const processImage = async () => {
    if (!originalImage) return;
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(originalImage);
      const blob = await response.blob();

      const formData = new FormData();
      formData.append('image', blob, 'image.jpg');
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const res = await axios.post(`${API_URL}/process-image`, formData);
      setProcessedImage(`data:image/jpeg;base64,${res.data.processed_image}`);
    } catch (e) {
      setError('Processing failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="component-container">
      <input
        type="file"
        accept="image/*"
        ref={fileInputRef}
        onChange={handleFileSelect}
      />

      <button onClick={processImage} disabled={loading || !originalImage}>
        {loading ? 'Processing...' : 'Process Image'}
      </button>

      {error && <div className="error">{error}</div>}

      <div style={{ display: 'flex', gap: '20px', marginTop: '20px' }}>
        {originalImage && <img src={originalImage} alt="Original" width="300" />}
        {processedImage && <img src={processedImage} alt="Processed" width="300" />}
      </div>
    </div>
  );
};

export default ImageProcessor;
